import{_ as r,o as t,c as e,a2 as l}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"鹰族","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/鹰族.md","filePath":"表层/种族/鹰族.md","lastUpdated":1787065118000}'),o={name:"表层/种族/鹰族.md"};function i(n,a,s,h,d,u){return t(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="鹰族" tabindex="-1">鹰族 <a class="header-anchor" href="#鹰族" aria-label="Permalink to &quot;鹰族&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>鹰族是羽族之一，以<strong>不习惯规则束缚、崇尚自由与力量</strong>为种族核心特质。共同体崩溃后，鹰族逐渐崛起，成为<strong>黑暗时代的主导者</strong>——擅长舆论把控，是第一批掌握魔法的种族，确立了对其他种族的奴隶制统治。黑暗时代结束后，鹰族沦为二流种族，彻底失去话语权，仅靠底蕴支持与及时站队才未丧失主权，行商成为该族目前的主要经济支柱。</p><hr><h2 id="体貌特征" tabindex="-1">体貌特征 <a class="header-anchor" href="#体貌特征" aria-label="Permalink to &quot;体貌特征&quot;">​</a></h2><ul><li><strong>形态</strong>：直立行走，具有鹰类猛禽的典型羽族福瑞形态。</li><li><strong>体格</strong>：羽族中体格最健壮。</li><li><strong>羽毛</strong>：以深棕、褐色为主，羽翼宽大。</li><li><strong>利爪</strong>：尖锐的爪部。</li><li><strong>飞行能力</strong>：有翅膀，可飞行。飞行速度与耐力在羽族中居前，优于鸽族。</li></ul><hr><h2 id="种族特质" tabindex="-1">种族特质 <a class="header-anchor" href="#种族特质" aria-label="Permalink to &quot;种族特质&quot;">​</a></h2><h3 id="核心特质-崇尚自由与力量" tabindex="-1">核心特质：崇尚自由与力量 <a class="header-anchor" href="#核心特质-崇尚自由与力量" aria-label="Permalink to &quot;核心特质：崇尚自由与力量&quot;">​</a></h3><ul><li><strong>自由至上</strong>：天生厌恶约束，不习惯规则束缚，对规则和制度有本能的排斥。</li><li><strong>力量崇拜</strong>：崇尚力量，将实力视为衡量一切的标准。</li><li><strong>舆论天赋</strong>：拥有突出的舆论把控能力，善于利用信息影响民众。</li></ul><hr><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to &quot;历史&quot;">​</a></h2><h3 id="共同体崩溃后-舆论崛起" tabindex="-1">共同体崩溃后：舆论崛起 <a class="header-anchor" href="#共同体崩溃后-舆论崛起" aria-label="Permalink to &quot;共同体崩溃后：舆论崛起&quot;">​</a></h3><p>共同体崩溃后，五大主族（鹿、熊、牛、甲、鹤）失去神明的直接保护，社会逐渐暴露出执政漏洞，引发许多民生与社会问题。鹰族在此期间从底层逐步崛起：</p><ul><li><strong>掌握舆论话语权</strong>：利用族群的舆论把控天赋，逐渐掌握了共同体内部的舆论话语权，完成了事实上的公信力转移。</li><li><strong>与甲族之灭的关联</strong>：鹰族曾通过多种舆论手段煽动民众对甲族的排异情绪，其间的具体经过与真相不属表层认知。详见 <a href="./甲族">甲族</a>。</li></ul><h3 id="黑暗时代-主导者" tabindex="-1">黑暗时代：主导者 <a class="header-anchor" href="#黑暗时代-主导者" aria-label="Permalink to &quot;黑暗时代：主导者&quot;">​</a></h3><p>共同体解体后，鹰族与猪族、蝠族、豹族、虎族合并组成<strong>新五族</strong>统治，鹰族处于核心领导地位：</p><ul><li><strong>第一批掌握魔法的种族</strong>：在鹰族带领下，新五族成为第一批掌握魔法的种族，并将魔法作为巩固统治、压制普通生灵的核心手段。</li><li><strong>框架的搭建者</strong>：黑暗时代的整个框架体系由鹰族搭建——<strong>强者为尊、贵族世袭</strong>等底层规则均为鹰族定下。其余四族为讨好鹰族、换取地位，逐渐细化出各种压迫手段。</li><li><strong>奴隶制统治</strong>：鹰族确立了对其他种族的奴隶制统治。牛族成为第一个彻底沦为奴隶的种族，鹿族则逐渐成为法师的助手/宠物。</li></ul><hr><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><h3 id="二流种族" tabindex="-1">二流种族 <a class="header-anchor" href="#二流种族" aria-label="Permalink to &quot;二流种族&quot;">​</a></h3><p>黑暗时代结束后，鹰族<strong>彻底失去话语权，沦为二流种族</strong>。仅靠<strong>深厚的底蕴支持</strong>与<strong>及时的立场站队</strong>，鹰族才未丧失主权——这是黑暗时代主导种族中极少数保住了部分独立的案例。</p><h3 id="行商为主" tabindex="-1">行商为主 <a class="header-anchor" href="#行商为主" aria-label="Permalink to &quot;行商为主&quot;">​</a></h3><p>行商成为鹰族目前的主要经济支柱。昔日的黑暗时代主导者，转而依靠商业往来维持种族的生存。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../历史/黑暗时代">黑暗时代</a></li><li><a href="./../历史/当前时代">当前时代</a></li><li><a href="./甲族">甲族</a></li><li><a href="./狼族">狼族</a></li></ul><h2 id="深层真相" tabindex="-1">深层真相 <a class="header-anchor" href="#深层真相" aria-label="Permalink to &quot;深层真相&quot;">​</a></h2><blockquote><p>甲族之灭的完整经过与鹰族舆论操作的内幕不属表层认知。</p></blockquote><ul><li><a href="./../../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></li></ul><hr>',31)])])}const b=r(o,[["render",i]]);export{g as __pageData,b as default};
